'use strict';
/* Original illustrated town with material-rich game art. All purchases use the existing v1 economy and save. */
(()=>{
const palette=[['#9ec6a6','#567e72','#f7dfac'],['#d98c81','#994f5c','#ffe0a8'],['#9fa7d8','#62668d','#e6d5ae'],['#8bbcc9','#477d96','#fae1b3'],['#9ebd85','#5b8268','#e0eac6'],['#b2a4d7','#68648e','#eae0c2']];
const goods=['月のお茶','雲のクロワッサン','星糸のリボン','流星のお手紙','夜光の花','星のランタン'];
const tiers=['小さなお店','にぎわうお店','星空の名店'];
let chosen=0,inside=false,signature='',fxUntil=0;
const oldRender=render,oldHud=hud;
const town=document.querySelector('.world');
town.innerHTML=`<div class="town-heading"><div><small>あなただけの、星の街。</small><h2>ほしみみ商店街 <span id="townOpen"></span></h2></div><button class="town-help" id="townHelp" aria-label="遊び方">?</button></div><div class="town-wallet"><div><small>✦ 星くず</small><b id="townMoney"></b></div><div><small>おまかせ売上</small><b id="townRate"></b></div><button id="townDelivery" class="gold">配達する +1</button></div><div class="town-map" id="townMap"><div class="town-map-label"><span id="worldStage"></span><span>お店をタップして入店 ↗</span></div><svg id="townCanvas" viewBox="0 0 420 600" role="group" aria-label="6つのお店が並ぶ商店街"></svg><div class="town-cloud c1"></div><div class="town-cloud c2"></div></div><div class="town-footer"><span id="worldCaption"></span><span id="townMood">☾ ほしみみの夜</span></div>`;
const modal=document.createElement('dialog');modal.id='shopRoom';modal.className='shop-room';modal.innerHTML='<div id="roomContent"></div>';document.body.appendChild(modal);
const atlas=(file,i,x,y,w,h,extra='')=>{const clip='sprite-'+file.replace(/\W/g,'')+'-'+i+'-'+String(x).replace('-','m')+'-'+String(y).replace('-','m')+'-'+w+'-'+h;return `<svg x="${x}" y="${y}" width="${w}" height="${h}" viewBox="0 0 512 512" preserveAspectRatio="xMidYMid meet" overflow="hidden" ${extra}><defs><clipPath id="${clip}"><rect width="512" height="512"/></clipPath></defs><g clip-path="url(#${clip})"><image x="${-(i%3)*512}" y="${-Math.floor(i/3)*512}" href="assets/${file}" width="1536" height="1024"/></g></svg>`};
const cat=(color,apron,size=1,i=0)=>`<g transform="scale(${size})">${atlas('shopkeepers-v3.webp',i,-21,-28,42,50)}</g>`;
const tree=(x,y,scale=1)=>`<g transform="translate(${x} ${y}) scale(${scale})"><ellipse cy="15" rx="17" ry="6" fill="#233e4929"/><path d="M0 0V16" stroke="#82716a" stroke-width="5"/><path d="M0-33L-16-9H-10L-20 3H20L10-9H16Z" fill="#709f91" stroke="#4d7773" stroke-width="2"/><path d="M0-27V-2" stroke="#b0cc9d" stroke-width="2"/></g>`;
const lamp=(x,y)=>`<g transform="translate(${x} ${y})"><ellipse cy="2" rx="10" ry="4" fill="#29424c33"/><path d="M0 0V-40Q0-49 9-49" fill="none" stroke="#546476" stroke-width="3"/><circle cx="10" cy="-43" r="22" fill="#ffdf9418"/><path d="M3-48H17L15-34H5Z" fill="#ffe6a4" stroke="#59657a" stroke-width="2"/><path d="M1-49H19" stroke="#59657a" stroke-width="3"/></g>`;
function symbol(i,x,y){const icons=[`<path d="M-12-7H9V4Q8 14-2 14T-12 4Z" fill="#d5edcd"/><path d="M9-4Q23-4 17 5H9M-7-13Q-12-20-5-25M1-13Q-4-20 3-25" fill="none" stroke="#f7edcc" stroke-width="3"/>`,`<path d="M-19 8Q-17-17 0-19 17-17 19 8L9 14 0 9-9 14Z" fill="#efba74"/><path d="M-10-7L-5 6M0-12L3 5M10-6L12 5" stroke="#b67a59" stroke-width="3"/>`,`<path d="M-17-15L-6-21Q0-13 6-21L17-15 13-1 8-4V16H-8V-4L-13-1Z" fill="#dcc7e5"/><path d="M0-10V12M-8 8H8" stroke="#a18dbf" stroke-width="2"/>`,`<rect x="-18" y="-13" width="36" height="27" rx="3" fill="#f6e9c7"/><path d="M-18-13L0 2 18-13M-18 14L-5 0M18 14L5 0" fill="none" stroke="#cc956f" stroke-width="2"/>`,`<path d="M0 16V-8M0 8Q-21 7-14-8 0-8 0 8M0 1Q21-1 14-16 0-16 0 1" fill="#b7d492" stroke="#678a72" stroke-width="2"/><circle cy="-15" r="8" fill="#e9cae0"/><circle cy="-15" r="3" fill="#ffe8a3"/>`,`<path d="M-12-13H12L10 16H-10Z" fill="#ffe6a4"/><path d="M-15-14H15M-11 16H11M-7-14V-22H7V-14M0-12V15" stroke="#817693" stroke-width="3" fill="none"/>`];return `<g transform="translate(${x} ${y})" stroke="#68596b" stroke-width="1.6" stroke-linejoin="round">${icons[i]}</g>`}
function building(i){
const x=i%2?227:13,y=73+Math.floor(i/2)*164,n=s.shops[i].n,t=n>=25?2:n>=5?1:0,open=n>0,title=defs[i][0];
const scale=[.83,.93,1.03][t];
let art=open?`<ellipse cx="84" cy="130" rx="78" ry="13" fill="#18252266"/><g transform="translate(${85*(1-scale)} ${135*(1-scale)}) scale(${scale})">${atlas('shops-v3.webp',i,-7,-28,185,170,'class="real-store"')}</g><g transform="translate(130 116)">${cat(null,null,1,i)}</g>${t===2?'<path d="M7 130V97M162 130V97" stroke="#ac8c59" stroke-width="2"/><circle cx="7" cy="96" r="4" fill="#ffe5a0"/><circle cx="162" cy="96" r="4" fill="#ffe5a0"/><text x="85" y="-14" fill="#f7dc9f" text-anchor="middle" font-size="12">✦ 星空の名店 ✦</text>':''}${s.shops[i].auto?`<g class="sale-bubble" style="animation-delay:${i*.6}s"><rect x="120" y="56" width="40" height="22" rx="11" fill="#ffedb9"/><text x="140" y="71" text-anchor="middle" font-size="12" fill="#8c7554">✦ +</text></g>`:''}`:`<path d="M8 120L85 94 165 120 85 148Z" fill="#73877b" stroke="#9ca18b" stroke-width="2"/><path d="M30 115L85 97 143 115" fill="none" stroke="#c5bea0" stroke-width="2" stroke-dasharray="5 5"/><path d="M63 93V126M107 93V123" stroke="#8a6e50" stroke-width="4"/><rect x="50" y="65" width="72" height="40" rx="4" fill="#cfb78b" stroke="#6b5644" stroke-width="2"/><text x="86" y="91" text-anchor="middle" fill="#6f5a46" font-size="22">＋</text><text x="85" y="48" text-anchor="middle" fill="#e4d6b7" font-size="10">ここにお店を建てよう</text>`;
return `<g class="town-building ${open?'is-open':'is-empty'}" role="button" tabindex="0" data-shop="${i}" aria-label="${title}、${open?'レベル'+n+'、入店':'未開店、建設する'}" transform="translate(${x} ${y})"><title>${title}</title>${art}<g transform="translate(5 145)"><rect width="164" height="25" rx="12" fill="${open?'#efe1bd':'#b1b59a'}" stroke="#8e8065"/><text x="82" y="17" text-anchor="middle" font-size="11" font-weight="600" fill="#574b3f">${open?title+' · Lv.'+n:title+' · 未開店'}</text></g></g>`;
}
function draw(){const count=s.shops.filter(x=>x.n).length;const trees=count>2?[tree(202,63,.6),tree(12,229,.7),tree(408,228,.7),tree(202,556,.8),tree(13,553,.7),tree(406,553,.7)].join(''):[tree(202,63,.6),tree(202,556,.8)].join('');
$('townCanvas').innerHTML=`<defs><linearGradient id="townGround" x2="0" y2="1"><stop stop-color="#657d6c"/><stop offset="1" stop-color="#3d574f"/></linearGradient><pattern id="paving" width="28" height="18" patternUnits="userSpaceOnUse"><path d="M0 0H28V18H0ZM14 0V9M0 9H28" fill="#b9aa8c" stroke="#a0937c" stroke-width=".8"/></pattern><linearGradient id="sky" x2="0" y2="1"><stop stop-color="#c3c6da"/><stop offset="1" stop-color="#f1d6bb"/></linearGradient></defs><rect width="420" height="600" fill="url(#townGround)"/><path d="M0 0H420V63Q330 47 280 60 190 80 105 57 46 46 0 64Z" fill="url(#sky)"/><circle cx="354" cy="23" r="19" fill="#fff1bf"/><path d="M0 48Q45 27 93 49T186 47T285 49T420 45V70H0Z" fill="#91aaa8"/><path d="M178 64H222V562H178Z" fill="url(#paving)"/><path d="M0 224H420V247H0ZM0 388H420V411H0Z" fill="url(#paving)"/><path d="M0 566H420V600H0Z" fill="url(#paving)"/><path d="M178 64V562M222 64V562M0 224H420M0 247H420M0 388H420M0 411H420" stroke="#637867" stroke-width="2"/>${trees}${count>1?lamp(201,218)+lamp(201,384):''}${count>3?lamp(13,390)+lamp(407,390):''}<g><rect x="146" y="26" width="125" height="30" rx="6" fill="#f7e6c4" stroke="#818c86" stroke-width="2"/><path d="M154 55V74M263 55V74" stroke="#818c86" stroke-width="4"/><text x="208" y="46" text-anchor="middle" fill="#6c6674" font-size="15" font-weight="700">ほしみみ商店街</text></g>${defs.map((_,i)=>building(i)).join('')}<g aria-hidden="true" class="town-residents">${Array.from({length:Math.max(2,count+1)},(_,i)=>`<g class="walking-cat"><animateMotion dur="${18+i*4}s" repeatCount="indefinite" path="${i%2?'M-25 236L445 236L445 400L-25 400Z':'M200 630L200 75L200 630'}" begin="-${i*5}s"/><g class="cat-step" style="animation-delay:-${i*.2}s">${cat(['#f0d0a9','#c0cad2','#e3bda8','#e2ddd2'][i%4],['#a4bca3','#cf9c9b','#a4a6cd'][i%3],.64,i%6)}</g></g>`).join('')}</g><g><path d="M22 584H53M28 578V589M48 578V589" stroke="#977f70" stroke-width="4"/><path d="M350 582H390M355 574V590M385 574V590" stroke="#977f70" stroke-width="4"/></g>`;
$('townCanvas').querySelectorAll('[data-shop]').forEach(el=>{el.onclick=()=>enter(+el.dataset.shop);el.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();enter(+el.dataset.shop)}}});
}
function roomArt(i){
const n=s.shops[i].n;
const bg=`<svg width="360" height="270" viewBox="${i%3*512} ${Math.floor(i/3)*512} 512 512" preserveAspectRatio="xMidYMid slice" overflow="hidden"><image href="assets/interiors-v3.webp" width="1536" height="1024"/></svg>`;
return `<svg viewBox="0 0 360 270" role="img" aria-label="${defs[i][0]}の店内。毛並みのある猫店員と木製カウンターと商品"><defs><clipPath id="counterFront"><rect y="194" width="360" height="76"/></clipPath><radialGradient id="roomLight"><stop stop-color="#ffe5a6" stop-opacity=".2"/><stop offset="1" stop-color="#ffe5a6" stop-opacity="0"/></radialGradient></defs>${bg}<ellipse cx="185" cy="125" rx="110" ry="120" fill="url(#roomLight)"/>${n?`<g class="real-worker">${atlas('shopkeepers-v3.webp',i,97,32,177,210)}</g>`:''}<g clip-path="url(#counterFront)">${bg}</g>${n?'':'<rect width="360" height="245" fill="#17231f99"/><text x="180" y="126" text-anchor="middle" fill="#e9d7ad" font-size="14">開店後の店内イメージ</text>'}<path d="M0 245H360V270H0Z" fill="#1a1717" opacity=".5"/><text x="180" y="262" text-anchor="middle" font-size="11" fill="#fff0cc">${n?'「いらっしゃいませ。'+defs[i][5]+'のお店へようこそ。」':'お店を開くと、'+defs[i][5]+'がここで店番します。'}</text></svg>`;
}
function enter(i){chosen=i;inside=true;room();if(!modal.open)modal.showModal();roomHUD()}
function room(){const i=chosen,n=s.shops[i].n,t=n>=25?2:n>=5?1:0;modal.innerHTML=`<div class="room-top"><div><small>${n?tiers[t]:'空き区画'} · ${defs[i][5]}のお店</small><h2>${defs[i][0]}</h2></div><button id="roomClose" aria-label="商店街へ戻る">×</button></div><div class="room-art ${n?'':'not-open'}">${roomArt(i)}</div><div class="room-body"><div class="room-summary"><span><small>お店のレベル</small><b>Lv.${n}</b></span><span><small>${goods[i]}の売上</small><b>✦ ${fmt(value(i))}<small> / ${defs[i][4]}秒</small></b></span></div><div class="bar"><div id="roomProgress" class="fill"></div></div><p class="room-story">${n?(s.shops[i].auto?defs[i][5]+'がお店を切り盛り中。閉じている間も売上が貯まります。':'「'+goods[i]+'、できたてをお届けしよう！」お店を動かして最初のお客さんを迎えよう。'):'この場所には、まだ灯りがありません。最初のお店を建てて、商店街に仲間を迎えよう。'}</p><div class="room-actions"><button class="gold" id="roomBuy">${n?'お店を育てる':'お店を建てる'}<small>✦ ${fmt(cost(i,1))} · Lv.${n+1}</small></button><button class="pill" id="roomRun">${s.shops[i].auto?'✓ おまかせ経営':s.shops[i].p?'接客中…':'▶ お店を動かす'}<small>${s.shops[i].auto?'店員が働いています':'✦ '+fmt(value(i))+' / 回'}</small></button></div><button class="room-hire" id="roomHire">${s.shops[i].auto?'✓ '+defs[i][5]+'が仲間になりました':defs[i][5]+'を雇う · ✦ '+fmt(autoCost(i))+'（自動化）'}</button><div class="room-next">${t<2?'次の外観：Lv.'+(t===0?5:25)+'で「'+tiers[t+1]+'」へ。':'星空の名店になりました。25レベルごとに売上が2倍になります。'}</div></div>`;
$('roomClose').onclick=()=>modal.close();$('roomBuy').onclick=()=>{if(s.money<cost(i,1)||s.shops[i].n>=10000)return;const prev=quantity;try{quantity=1;buy(i)}finally{quantity=prev}render();toast(defs[i][0]+(n?'が成長した！':'が開店した！'));};$('roomRun').onclick=()=>{const x=s.shops[i];if(x.n&&!x.auto&&!x.p){x.p=.001;save();room();}};$('roomHire').onclick=()=>hire(i);roomHUD();}
function roomHUD(){if(!inside||!modal.open)return;const x=s.shops[chosen];$('roomProgress').style.width=x.p/defs[chosen][4]*100+'%';$('roomBuy').disabled=s.money<cost(chosen,1)||x.n>=10000;$('roomRun').disabled=!x.n||x.auto||!!x.p;$('roomRun').firstChild.textContent=x.auto?'✓ おまかせ経営':x.p?'接客中…':'▶ お店を動かす';$('roomHire').disabled=!x.n||x.auto||s.money<autoCost(chosen);}
modal.addEventListener('close',()=>inside=false);modal.addEventListener('click',e=>{if(e.target===modal){const r=modal.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)modal.close()}});
function update(){const key=s.shops.map(x=>x.n+':'+x.auto).join('|')+':'+s.ups.length+':'+s.stars;if(key!==signature){signature=key;draw();if(inside)room();}$('townMoney').textContent=fmt(s.money);$('townRate').textContent='✦ '+fmt(rate())+' / 秒';$('townDelivery').textContent='✦ 配達 +'+fmt(Math.max(1,rate()*.1));$('townOpen').textContent=s.shops.filter(x=>x.n).length+'/6 店';roomHUD();}
render=function(){oldRender();update()};hud=function(){oldHud();update()};
$('townDelivery').onclick=e=>{const n=Math.max(1,rate()*.1);gain(n);hud();const p=document.createElement('span');p.className='float-gain';p.textContent='✦ +'+fmt(n);p.style.left=(e.clientX||innerWidth/2)+'px';p.style.top=(e.clientY||120)+'px';document.body.append(p);setTimeout(()=>p.remove(),950)};
$('townHelp').onclick=()=>toast('お店をタップ → 建てる → 動かす → 店員を雇う。Lv.5と25で外観が変わるよ。');
// The town is the main play surface. Detailed management remains below it.
document.body.classList.add('town-edition');document.querySelector('h1 span').textContent='ぬくもりの街版';update();
})();
